inline LocalizedMessage electricityPanelMessage(std::string_view language,ElectricityPanelMessageKey key){
    const auto index=static_cast<std::size_t>(key);if(index>=electricityPanelMessageKeyCount)return {};
    const auto &source=electricityPanelLocalePacks()[0];const auto *selected=&source;for(const auto &pack:electricityPanelLocalePacks())if(pack.id==language){selected=&pack;break;}
    if(selected->id!=language||!validTemplateTranslation(source.messages[index],selected->messages[index]))return {source.messages[index],source.id,source.review,true,false};
    return {selected->messages[index],selected->id,selected->review,false,selected->rtl};
}
inline std::string electricityPanelEnglish(ElectricityPanelMessageKey key){return std::string(electricityPanelMessage("en",key).text);}
